"""Round-robin job scheduler module."""


def _get_enabled_workers(workers: list[dict]) -> list[str]:
    """Return names of enabled workers."""
    return [w["name"] for w in workers if w.get("enabled", True)]


def _try_assign_job(
    job: str,
    enabled_workers: list[str],
    index: int,
    assigned_counts: dict[str, int],
    capacities: dict[str, int] | None,
) -> tuple[dict | None, int]:
    """Try to assign a single job to the next available worker.

    Returns a (result_row_or_None, updated_index) tuple.
    """
    num_workers = len(enabled_workers)
    for _ in range(num_workers):
        worker_name = enabled_workers[index % num_workers]
        index += 1

        if capacities is not None:
            cap = capacities.get(worker_name)
            if cap is not None and assigned_counts[worker_name] >= cap:
                continue

        assigned_counts[worker_name] += 1
        return {"job": job, "worker": worker_name}, index

    return None, index


def assign_round_robin(
    workers: list[dict],
    jobs: list[str],
    capacities: dict[str, int] | None = None,
) -> list[dict]:
    """Assign jobs to enabled workers in round-robin order.

    Args:
        workers: List of worker dicts with "name" and optional "enabled" fields.
        jobs: List of job names to assign.
        capacities: Optional mapping of worker name to maximum number of jobs
            that worker may receive.  Workers absent from the mapping have no
            cap.  Jobs that cannot be assigned due to capacity limits are
            omitted from the result.

    Returns:
        List of dicts shaped as {"job": str, "worker": str}.

    Raises:
        TypeError: If arguments are of wrong types.
        ValueError: If there are no enabled workers, or if worker dicts are
            malformed, or if capacity values are not positive integers.
    """
    # --- input validation ---
    if not isinstance(workers, list):
        raise TypeError(
            f"'workers' must be a list, got {type(workers).__name__!r}"
        )
    if not isinstance(jobs, list):
        raise TypeError(
            f"'jobs' must be a list, got {type(jobs).__name__!r}"
        )
    if capacities is not None and not isinstance(capacities, dict):
        raise TypeError(
            f"'capacities' must be a dict or None, got {type(capacities).__name__!r}"
        )

    for idx, worker in enumerate(workers):
        if not isinstance(worker, dict):
            raise TypeError(
                f"Each worker must be a dict; workers[{idx}] is "
                f"{type(worker).__name__!r}"
            )
        if "name" not in worker:
            raise ValueError(
                f"Worker at index {idx} is missing required field 'name'."
            )
        if not isinstance(worker["name"], str):
            raise TypeError(
                f"Worker 'name' must be a str; workers[{idx}]['name'] is "
                f"{type(worker['name']).__name__!r}"
            )
        if not worker["name"]:
            raise ValueError(
                f"Worker 'name' must be a non-empty string; workers[{idx}] has "
                f"an empty name."
            )
        enabled = worker.get("enabled", True)
        if not isinstance(enabled, bool):
            raise TypeError(
                f"Worker 'enabled' must be a bool; workers[{idx}]['enabled'] is "
                f"{type(enabled).__name__!r}"
            )

    for job_idx, job in enumerate(jobs):
        if not isinstance(job, str):
            raise TypeError(
                f"Each job must be a str; jobs[{job_idx}] is "
                f"{type(job).__name__!r}"
            )

    if capacities is not None:
        for key, value in capacities.items():
            if not isinstance(key, str):
                raise TypeError(
                    f"Capacity keys must be strings; got key {key!r} of type "
                    f"{type(key).__name__!r}"
                )
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(
                    f"Capacity values must be integers; capacities[{key!r}] is "
                    f"{type(value).__name__!r}"
                )
            if value < 0:
                raise ValueError(
                    f"Capacity values must be non-negative; "
                    f"capacities[{key!r}] = {value}"
                )

    # --- core algorithm (unchanged) ---
    enabled_workers = _get_enabled_workers(workers)

    if not enabled_workers:
        raise ValueError("No enabled workers available.")

    result = []
    assigned_counts: dict[str, int] = {name: 0 for name in enabled_workers}
    index = 0

    for job in jobs:
        row, index = _try_assign_job(
            job, enabled_workers, index, assigned_counts, capacities
        )
        if row is not None:
            result.append(row)

    return result

